/** Player_t (player.h) */
export class Player_t {
  readonly misc = new PlayerMisc();
  /** Stats now kept in arrays, for more efficient access. -CJS- */
  readonly stats = new PlayerStats();
  readonly flags = new PlayerFlags();
  /** location in dungeon */
  readonly pos: Coord_t = { y: 0, x: 0 };
  private _prev_dir = 32;
  /** Direction memory. -CJS- (a C char holding 1..9; initially ' ' = 32) */
  get prev_dir(): number { return this._prev_dir; }
  set prev_dir(v: number) { this._prev_dir = (v << 24) >> 24; }
  /** calculated base hp values at each level */
  readonly base_hp_levels = new Uint16Array(PLAYER_MAX_LEVEL);
  /** Base experience levels, may be adjusted up for race and/or class */
  readonly base_exp_levels = new Uint32Array(PLAYER_MAX_LEVEL);
  private _running_tracker = 0;
  /** Tracker for number of turns taken during one run cycle */
  get running_tracker(): number { return this._running_tracker; }
  set running_tracker(v: number) { this._running_tracker = v & 0xff; }
  /** Track if temporary light about player */
  temporary_light_only = false;
  private _max_score = 0;
  /** Maximum score attained */
  get max_score(): number { return this._max_score; }
  set max_score(v: number) { this._max_score = v | 0; }
  readonly pack = new PlayerPack();
  readonly inventory: readonly Inventory_t[] = Array.from({ length: PLAYER_INVENTORY_SIZE }, () => new Inventory_t());
  private _equipment_count = 0;
  /** Number of equipped items */
  get equipment_count(): number { return this._equipment_count; }
  set equipment_count(v: number) { this._equipment_count = (v << 16) >> 16; }
  /** Weapon is too heavy -CJS- */
  weapon_is_heavy = false;
  /** `true` when player is carrying light */
  carrying_light = false;

  /** C struct assignment: copies every field of `o` into this. */
  assign(o: Player_t): this {
    this.misc.assign(o.misc);
    this.stats.assign(o.stats);
    this.flags.assign(o.flags);
    this.pos.y = o.pos.y;
    this.pos.x = o.pos.x;
    this._prev_dir = o._prev_dir;
    this.base_hp_levels.set(o.base_hp_levels);
    this.base_exp_levels.set(o.base_exp_levels);
    this._running_tracker = o._running_tracker;
    this.temporary_light_only = o.temporary_light_only;
    this._max_score = o._max_score;
    this.pack.assign(o.pack);
    for (let i = 0; i < PLAYER_INVENTORY_SIZE; i++) this.inventory[i].assign(o.inventory[i]);
    this._equipment_count = o._equipment_count;
    this.weapon_is_heavy = o.weapon_is_heavy;
    this.carrying_light = o.carrying_light;
    return this;
  }

  clone(): Player_t {
    return new Player_t().assign(this);
  }
}

